pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address attacker, uint256 amount) internal {
        vm.assume(true);
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted || amount > 0 || attacker != msg.sender);
    }

    function testFuzz_run(address attacker, uint256 amount) public {
        _run(attacker, amount);
    }

    receive() external payable {}
}
